-- Migration: Question generation — AUD batch 18 (30 questions)
-- Date: 2026-02-23
-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Accumulating misstatements above clearly trivial threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Bridgeport Electronics, the engagement team sets overall materiality at $200,000 and the clearly trivial threshold at $10,000. The team identifies a $12,500 inventory pricing error. Under AU-C 450, the auditor should:', '["Disregard the error because it falls below performance materiality", "Report the error immediately to those charged with governance as a material weakness", "Accumulate the misstatement on the summary of uncorrected misstatements", "Require management to correct the error before issuing the audit report"]'::jsonb, 2, 'Under AU-C 450.05, the auditor must accumulate all identified misstatements during the audit other than those that are clearly trivial. Because the $12,500 error exceeds the $10,000 clearly trivial threshold, it must be added to the summary of uncorrected misstatements for evaluation. Choice A is incorrect because the relevant threshold for accumulation is clearly trivial, not performance materiality.', 'medium', 2),

-- Q2: medium / L3 — Qualitative materiality and earnings trend reversal
(1, 'Misstatements and Control Deficiencies', 'Granite Peak Distributors reports net income of $1,050,000 for the current year compared to $980,000 in the prior year. The auditor identifies an uncorrected overstatement of revenue totaling $85,000. Materiality is $100,000. The auditor should analyze this misstatement by considering that:', '["The misstatement is immaterial because it falls below the $100,000 quantitative threshold", "Correcting the misstatement would reverse the trend from increasing to decreasing net income, making it qualitatively material", "Qualitative factors are only relevant when the misstatement exceeds materiality", "The misstatement affects only revenue and therefore cannot impact the overall financial statement opinion"]'::jsonb, 1, 'Under AU-C 450.11, the auditor must consider both quantitative and qualitative factors when evaluating uncorrected misstatements. Even though the $85,000 misstatement is below the $100,000 materiality threshold, correcting it would reduce net income to $965,000, below the prior year''s $980,000, reversing an earnings trend. Choice A is incorrect because a misstatement below quantitative materiality may still be material when qualitative factors are considered.', 'medium', 3),

-- Q3: medium / L3 — Classifying judgmental misstatement from unreasonable estimate
(1, 'Misstatements and Control Deficiencies', 'While auditing Cedar Valley Health Systems, the engagement team discovers that management estimated the allowance for uncollectible patient accounts at $340,000 using a 4% rate. Industry data and historical experience support a range of 5% to 7%. The auditor concludes the estimate falls outside the reasonable range. This difference is best classified as a:', '["Judgmental misstatement because it arises from a difference in management''s estimate versus the auditor''s assessment of the reasonable range", "Factual misstatement because the auditor has conclusive evidence that the estimate is wrong", "Projected misstatement because the difference was identified through analytical procedures", "Known misstatement because the amount of the understatement can be precisely calculated"]'::jsonb, 0, 'Under AU-C 450.A4, a judgmental misstatement arises from differences in management''s judgments concerning accounting estimates that the auditor considers unreasonable, or the selection or application of accounting policies the auditor considers inappropriate. Because the estimate falls outside the reasonable range, it is a judgmental misstatement. Choice B is incorrect because factual misstatements involve errors about which there is no doubt, not disputes over estimates.', 'medium', 3),

-- Q4: easy / L1 — Performance materiality definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 320, performance materiality is defined as:', '["The maximum tolerable error rate in a population of transactions", "The threshold below which misstatements are considered clearly trivial", "The level of materiality set by those charged with governance for internal reporting", "An amount set below overall materiality to reduce the probability that aggregate uncorrected misstatements exceed materiality"]'::jsonb, 3, 'Under AU-C 320.09, performance materiality is the amount or amounts set by the auditor at less than materiality for the financial statements as a whole to reduce to an appropriately low level the probability that the aggregate of uncorrected and undetected misstatements exceeds materiality. Choice A is incorrect because tolerable misstatement in sampling is a related but distinct concept applied at the individual test level.', 'easy', 1),

-- Q5: medium / L2 — Setting tolerable misstatement in substantive sampling
(1, 'Misstatements and Control Deficiencies', 'While planning substantive tests of Ridgeline Manufacturing''s accounts receivable balance of $3.2 million, the auditor sets overall materiality at $150,000 and performance materiality at $112,500. When selecting a sample for detail testing, the auditor should set tolerable misstatement at:', '["$150,000, equal to overall materiality for the financial statements", "An amount at or below performance materiality to allow for undetected misstatements in other accounts", "$3,200, representing 0.1% of the account balance as a conservative threshold", "An amount equal to the expected misstatement plus a margin for sampling risk"]'::jsonb, 1, 'Under AU-C 530.A3, tolerable misstatement is the application of performance materiality to a particular sampling procedure. The auditor sets tolerable misstatement at or below performance materiality to allow for the possibility that misstatements in other accounts may also exist. Choice A is incorrect because using overall materiality as tolerable misstatement would not leave sufficient margin for undetected misstatements across all accounts.', 'medium', 2),

-- Q6: easy / L1 — Definition of clearly trivial
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, the term ''clearly trivial'' describes misstatements that are:', '["So small that they need not be accumulated because they would not affect decisions of financial statement users individually or in the aggregate", "Below the performance materiality threshold established during audit planning", "Immaterial to the financial statements but still required to be communicated to management", "Equal to zero, meaning only exact errors must be accumulated by the auditor"]'::jsonb, 0, 'Under AU-C 450.A2, clearly trivial is not another expression for "not material." Matters that are clearly trivial are of a wholly different and smaller magnitude than materiality and are amounts the auditor need not accumulate because such amounts would not be material individually or in the aggregate. Choice D is incorrect because clearly trivial establishes a de minimis threshold above zero, not a requirement to report only exact errors.', 'easy', 1),

-- Q7: medium / L3 — Magnitude and likelihood analysis for segregation of duties failure
(1, 'Misstatements and Control Deficiencies', 'During the audit of Maple Ridge Financial Group, the auditor identifies that the accounts payable manager can both approve invoices and process payments without independent review. Although no misstatement has been detected, the control processes $8 million in transactions annually. In evaluating severity under AU-C 265, the auditor should conclude that:', '["The deficiency is not reportable because no actual misstatement resulted from the weakness", "The deficiency is a significant deficiency because it involves a segregation of duties conflict", "The deficiency is a material weakness because the magnitude of transactions that could be affected is substantial and the likelihood of misstatement is more than remote", "The deficiency requires additional testing before any classification can be determined"]'::jsonb, 2, 'Under AU-C 265.A8, severity depends on the magnitude of the potential misstatement and the likelihood of occurrence. Although no misstatement was detected, the lack of segregation of duties over $8 million in annual transactions creates both a high magnitude of potential misstatement and a reasonable possibility of occurrence. Choice A is incorrect because deficiency evaluation considers potential misstatements, not only those actually detected.', 'medium', 3),

-- Q8: easy / L1 — Written communication timeline for control deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, written communication of significant deficiencies and material weaknesses to those charged with governance must be made:', '["Within 30 days of the audit report date", "Immediately upon identification during fieldwork", "Before the entity files its annual report with regulators", "No later than 60 days following the audit report release date"]'::jsonb, 3, 'Under AU-C 265.13, the auditor should communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. This timeline allows the auditor to complete the evaluation of all identified deficiencies before issuing the communication. Choice B is incorrect because while oral communication may occur during fieldwork, the formal written communication deadline is tied to the report release date.', 'easy', 1),

-- Q9: hard / L4 — Evaluating opinion modification when uncorrected misstatements approach materiality
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westbrook Pharmaceuticals, the engagement partner reviews the summary of uncorrected misstatements totaling $92,000 against overall materiality of $100,000. The misstatements consist of a $45,000 revenue overstatement, a $28,000 inventory overstatement, and a $19,000 understatement of accrued liabilities. Management provides a written representation that the effects are immaterial. The engagement partner should:', '["Accept management''s representation and issue an unmodified opinion because the aggregate is below materiality", "Evaluate whether the misstatements, together with the possibility of undetected misstatements, could cause the financial statements to be materially misstated", "Issue a qualified opinion because the aggregate uncorrected misstatements are within 10% of materiality", "Withdraw from the engagement because management''s refusal to correct indicates a lack of integrity"]'::jsonb, 1, 'Under AU-C 450.11, the auditor must evaluate whether uncorrected misstatements are material, individually or in aggregate, considering the size and nature of the misstatements and the effect of prior-period uncorrected misstatements. When the aggregate approaches materiality, the auditor must also consider undetected misstatements that may exist. Choice A is incorrect because management''s representation does not relieve the auditor of the responsibility to independently evaluate whether uncorrected misstatements render the financial statements materially misstated.', 'hard', 4),

-- Q10: medium / L2 — Qualitative materiality from debt covenant violation
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Capital Advisors reports compliance with debt covenants requiring a current ratio of at least 1.5:1. The auditor identifies an uncorrected $35,000 reclassification error that, if corrected, would reduce the current ratio from 1.52:1 to 1.47:1. Overall materiality is $200,000. The auditor should treat this misstatement as:', '["Qualitatively material because correction would cause a debt covenant violation, regardless of the quantitative amount", "Immaterial because $35,000 is well below the $200,000 materiality threshold", "A disclosure deficiency rather than a financial statement misstatement", "Clearly trivial because it involves only a reclassification, not an overstatement or understatement of net income"]'::jsonb, 0, 'Under AU-C 450.11, the auditor must consider qualitative factors when evaluating uncorrected misstatements, including whether the misstatement affects compliance with regulatory requirements or debt covenants. A $35,000 reclassification that triggers a covenant violation is qualitatively material despite being far below quantitative materiality. Choice B is incorrect because materiality is not determined solely by comparing the misstatement to a quantitative threshold when significant qualitative considerations exist.', 'medium', 2),

-- Q11: medium / L2 — Documentation requirements for uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Summit Ridge Technologies, the senior auditor compiles the documentation related to uncorrected misstatements. Under AU-C 450, the auditor''s working papers must include:', '["Only misstatements that individually exceed performance materiality", "A summary limited to factual misstatements, excluding projected and judgmental amounts", "Management''s signed acknowledgment that all misstatements have been corrected", "All accumulated misstatements identified during the audit, including management''s reasons for not making corrections"]'::jsonb, 3, 'Under AU-C 450.12, the auditor must document all misstatements accumulated during the audit on a summary of uncorrected misstatements, along with the basis for the auditor''s conclusion about whether they are material. AU-C 450.08 requires documenting management''s reasons for not correcting them. Choice A is incorrect because all misstatements above the clearly trivial threshold must be accumulated, not only those exceeding performance materiality.', 'medium', 2),

-- Q12: easy / L1 — Control deficiency definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a control deficiency exists when:', '["The auditor identifies a material misstatement in the financial statements", "Management fails to respond to the auditor''s management letter within 30 days", "A control is designed, implemented, or operated in a way that does not allow timely prevention or detection of misstatements", "The entity does not have a formal internal audit function"]'::jsonb, 2, 'Under AU-C 265.07, a deficiency in internal control exists when the design or operation of a control does not allow management or employees, in the normal course of performing their assigned functions, to prevent or detect and correct misstatements on a timely basis. Choice D is incorrect because the absence of an internal audit function does not automatically constitute a control deficiency.', 'easy', 1),

-- Q13: easy / L1 — Management representation letter content for uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 580, the management representation letter must include a representation that:', '["All control deficiencies identified during the audit have been fully remediated", "The effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole", "No misstatements of any amount exist in the financial statements", "The auditor''s materiality threshold was approved by the audit committee"]'::jsonb, 1, 'Under AU-C 580.A8, the management representation letter must include a statement that management believes the effects of uncorrected misstatements aggregated by the auditor are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of such items is typically attached. Choice C is incorrect because the representation acknowledges uncorrected misstatements may exist but asserts their effects are immaterial.', 'easy', 1),

-- Q14: medium / L3 — Personnel turnover impact on control environment
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearwater Medical Devices, the auditor learns that three senior accountants resigned during the year and their positions remained vacant for four months. During this period, routine account reconciliations were not performed. The auditor should analyze this situation as:', '["A control deficiency related to the control environment because inadequate staffing prevented timely operation of reconciliation controls", "A business risk outside the scope of the auditor''s evaluation of internal controls", "A significant deficiency only if a material misstatement was actually detected in the unreconciled accounts", "An inherent limitation of internal control that requires no further evaluation"]'::jsonb, 0, 'Under AU-C 265.A1, control deficiencies may arise from the design or operation of controls. Failure to perform reconciliations due to staffing gaps represents an operational failure in the control environment component of COSO. The deficiency exists regardless of whether a misstatement resulted because the control was not operating to prevent or detect errors. Choice C is incorrect because deficiency classification considers the potential for misstatement, not only whether one was actually detected.', 'medium', 3),

-- Q15: hard / L3 — IT general controls failure cascading to application controls
(1, 'Misstatements and Control Deficiencies', 'While auditing Northstar Financial Services, the auditor discovers that the IT department did not restrict access to the general ledger system during the year, allowing unauthorized users to post journal entries. The entity relies on an automated three-way match control for accounts payable. The auditor should analyze the impact of the access control failure by concluding that:', '["The automated three-way match remains effective because it operates independently of user access controls", "Only manual controls are affected by the access control failure because automated controls are programmed", "The access failure is limited to the general ledger and does not affect the accounts payable subledger", "The reliability of the automated three-way match is compromised because IT general controls over access support the integrity of all application controls"]'::jsonb, 3, 'Under AU-C 315.A72, IT general controls support the continued proper operation of application controls. When access controls over a financial system are deficient, the auditor cannot rely on automated application controls that depend on the integrity of the system, including the three-way match. Choice A is incorrect because automated application controls are dependent on IT general controls for their continued effective operation.', 'hard', 3),

-- Q16: hard / L4 — Governance disagrees with material weakness classification
(1, 'Misstatements and Control Deficiencies', 'After the audit of Heritage Banking Corporation, the engagement partner classifies a deficiency in the loan loss reserve estimation process as a material weakness. The audit committee disagrees, arguing that a compensating detective control — quarterly portfolio reviews by the chief credit officer — reduces the severity to a significant deficiency. The compensating control was tested and found effective. The engagement partner should:', '["Defer to the audit committee''s assessment because they have superior knowledge of the entity''s operations", "Reclassify the deficiency as a significant deficiency based on the audit committee''s evidence of compensating controls", "Evaluate whether the compensating control sufficiently reduces the likelihood and magnitude of potential misstatement, but retain the final classification determination as an auditor judgment", "Report the disagreement to the entity''s bank regulators as required by GAGAS"]'::jsonb, 2, 'Under AU-C 265.A12, the auditor should consider compensating controls when evaluating severity, but the final determination of whether a deficiency is a material weakness remains the auditor''s professional judgment. While the effective compensating control is relevant evidence, the auditor must independently assess whether it reduces the reasonable possibility of material misstatement. Choice A is incorrect because the classification of control deficiencies is the auditor''s responsibility, not the audit committee''s.', 'hard', 4),

-- Q17: medium / L3 — Prior-year uncorrected misstatements affecting current year
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Sterling Manufacturing, the auditor identified a $60,000 understatement of warranty accrual expense that management declined to correct. In the current year, the warranty obligations related to those prior-year transactions were settled for actual costs consistent with the auditor''s estimate. The auditor should analyze the effect on current-year financial statements by recognizing that:', '["The prior-year understatement has no effect because the warranties were settled in the current year", "The current-year income statement is affected because the settlement of the under-accrued liability increases current-year warranty expense by approximately $60,000", "Only the balance sheet is affected because the warranty accrual was a prior-year liability", "The auditor must restate the prior-year financial statements before evaluating current-year effects"]'::jsonb, 1, 'Under AU-C 450.A6, the auditor must evaluate the effect of uncorrected misstatements from prior periods on the current year. When a prior-year warranty accrual was understated and the obligations are settled in the current year, the unrecorded expense from the prior year flows into the current year as additional expense. Choice A is incorrect because the settlement of under-accrued liabilities creates a current-year income statement effect even though the underlying transactions originated in the prior year.', 'medium', 3),

-- Q18: medium / L2 — Auditor response to misstatement corrected during interim testing
(1, 'Misstatements and Control Deficiencies', 'During interim testing at Cascade Valley Logistics in September 2025, the auditor identifies a $22,000 overstatement in prepaid insurance that originated in June 2025. The entity''s year-end is December 31, 2025. Management corrects the error immediately. Under AU-C 450, the auditor should:', '["Evaluate whether the correction was properly recorded and perform procedures at year-end to determine that additional similar errors did not occur in the remaining period", "Treat the error as fully resolved and exclude it from further audit consideration", "Include the $22,000 on the summary of uncorrected misstatements despite the correction", "Request management to restate the interim financial statements filed with regulators"]'::jsonb, 0, 'Under AU-C 450.07, when management corrects a misstatement, the auditor should evaluate whether additional misstatements may exist. Because the error was identified during interim testing, the auditor must perform rollforward procedures to verify that similar errors did not occur in the October through December period and that the correction was properly recorded. Choice B is incorrect because correction of an identified error does not eliminate the risk that the same type of error occurred in untested periods.', 'medium', 2),

-- Q19: medium / L2 — Deficiency below significant deficiency threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Horizon Wellness Group, the auditor identifies a control deficiency in the petty cash reimbursement process: receipts under $50 are occasionally missing supporting documentation. Petty cash transactions total $3,200 for the year, and overall materiality is $250,000. Under AU-C 265, the auditor should:', '["Communicate the deficiency in writing to those charged with governance as a significant deficiency", "Classify the deficiency as a material weakness because any missing documentation indicates a control failure", "Issue a qualified audit opinion due to the scope limitation on petty cash testing", "Communicate the deficiency to management, either orally or in writing, but it does not rise to the level requiring written communication to governance"]'::jsonb, 3, 'Under AU-C 265.12, the auditor should communicate to management control deficiencies identified during the audit that are not significant deficiencies or material weaknesses but are of sufficient importance to merit management''s attention. Given the immaterial dollar amount of $3,200, this deficiency does not meet the significant deficiency threshold. Choice A is incorrect because written communication to governance is required only for significant deficiencies and material weaknesses.', 'medium', 2),

-- Q20: hard / L4 — Evaluating whether remediation plan changes current-year classification
(1, 'Misstatements and Control Deficiencies', 'After identifying a material weakness in revenue recognition controls at Crestfield Industries, management presents a detailed remediation plan including hiring a revenue accounting specialist and implementing automated contract review software by March 2026. The current audit period ends December 31, 2025. The engagement partner should:', '["Downgrade the deficiency to a significant deficiency because management''s remediation plan demonstrates a commitment to correction", "Delay the written communication until March 2026 to assess whether the remediation is effective", "Report the material weakness as it existed at the balance sheet date, noting that management''s remediation plan does not change the classification for the current period", "Include the remediation plan in the audit opinion as an emphasis-of-matter paragraph"]'::jsonb, 2, 'Under AU-C 265.A17, the existence of a remediation plan does not affect the auditor''s responsibility to communicate deficiencies as they existed during the audit period. The material weakness must be reported based on conditions at December 31, 2025, because the remediation had not been implemented or tested as of that date. Choice A is incorrect because deficiency classification is based on conditions that existed during the period under audit, not on management''s plans for future corrective action.', 'hard', 4),

-- Q21: medium / L3 — Segregation of duties failure affecting multiple assertions
(1, 'Misstatements and Control Deficiencies', 'While auditing Lakewood Supply Chain Inc., the auditor discovers that the warehouse manager both receives incoming shipments and records inventory quantities in the perpetual system without independent verification. The auditor should analyze this deficiency by recognizing that it primarily affects:', '["Both the existence and completeness assertions for inventory because the same individual could overstate quantities to conceal theft or understate quantities to hide shortages", "Only the valuation assertion because inventory quantities feed into the cost calculations", "Only the existence assertion because the primary risk is recording fictitious inventory", "The presentation and disclosure assertion because the inventory note disclosures may be inaccurate"]'::jsonb, 0, 'Under AU-C 315.A70, the auditor must consider which financial statement assertions are affected by a control deficiency. When one individual controls both receiving and recording without oversight, inventory could be overstated through fictitious receipts (existence) or understated through unrecorded diversions (completeness). Choice C is incorrect because limiting the analysis to existence ignores the completeness risk that arises when the same person could divert goods without recording their receipt.', 'medium', 3),

-- Q22: medium / L3 — Single deficiency spanning multiple transaction classes increases severity
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Shore Properties, the auditor identifies that the same individual approves vendor invoices, tenant rental adjustments, and property maintenance expenditures without secondary authorization. Each of these three transaction classes exceeds $2 million annually. In evaluating severity under AU-C 265, the most important factor is that:', '["The deficiency affects only routine transactions that are unlikely to contain material errors", "The individual has been with the company for 15 years without any prior incidents", "Each transaction class should be evaluated separately when determining deficiency severity", "The deficiency affects multiple transaction classes, increasing the magnitude of transactions that could be materially misstated"]'::jsonb, 3, 'Under AU-C 265.A8, the magnitude of the potential misstatement is a primary factor in evaluating severity. When a single control deficiency spans multiple transaction classes totaling over $6 million, the cumulative magnitude is substantially greater than if only one class were affected. Choice C is incorrect because AU-C 265 requires the auditor to evaluate deficiencies both individually and in combination, and a deficiency spanning multiple classes should be assessed holistically.', 'medium', 3),

-- Q23: easy / L1 — Communication of lesser deficiencies to management
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, control deficiencies that are less severe than significant deficiencies should be communicated to:', '["Those charged with governance in writing within 60 days of the report release date", "Management on a timely basis, either orally or in writing", "The entity''s external legal counsel for regulatory compliance purposes", "The internal audit department for remediation tracking"]'::jsonb, 1, 'Under AU-C 265.12, the auditor should communicate to management on a timely basis control deficiencies identified during the audit that are of sufficient importance to merit management''s attention but do not rise to the level of significant deficiencies or material weaknesses. This communication may be oral or written. Choice A is incorrect because written communication to governance is required only for significant deficiencies and material weaknesses.', 'easy', 1),

-- Q24: hard / L4 — Fraud discovery changes deficiency severity assessment
(1, 'Misstatements and Control Deficiencies', 'During the audit of Beacon Hill Financial Advisors, the auditor discovers that a staff accountant exploited a control deficiency in the cash disbursement process to embezzle $18,000 over six months. Overall materiality is $350,000. Without the fraud, the auditor had initially classified the deficiency as a significant deficiency. Given the discovery of the actual fraud, the engagement partner should:', '["Maintain the significant deficiency classification because the $18,000 fraud is below materiality", "Report the fraud to law enforcement but leave the deficiency classification unchanged", "Reassess the severity of the deficiency as a potential material weakness because the occurrence of fraud indicates the control failed to prevent or detect misstatement, regardless of the dollar amount", "Reclassify the deficiency as a material weakness only if the cumulative embezzlement could reach materiality"]'::jsonb, 2, 'Under AU-C 265.A10, the discovery of fraud, regardless of amount, is a strong indicator that a control deficiency may be a material weakness because it demonstrates the control actually failed. The auditor must reassess whether a reasonable possibility exists that a material misstatement could occur, considering that the fraud proves the deficiency is exploitable. Choice A is incorrect because actual fraud fundamentally changes the likelihood assessment, even when the detected amount is below materiality.', 'hard', 4),

-- Q25: hard / L4 — Assessing pervasive vs. non-pervasive misstatements for opinion type
(1, 'Misstatements and Control Deficiencies', 'The auditor of Silverline Aerospace concludes that uncorrected misstatements in the financial statements are material. The misstatements consist of a $400,000 inventory overstatement and a $180,000 understatement of warranty liabilities, both affecting the same product line. Overall materiality is $500,000. The remaining financial statement line items are fairly stated. The engagement partner should assess whether:', '["The misstatements, although material, are confined to specific accounts and are not pervasive to the financial statements, indicating a qualified opinion is appropriate", "An adverse opinion is required because the aggregate misstatement of $580,000 exceeds overall materiality", "A disclaimer of opinion is necessary because management refused to make corrections", "An unmodified opinion with an emphasis-of-matter paragraph is sufficient to alert users"]'::jsonb, 0, 'Under AU-C 705.08, when the auditor concludes that misstatements are material, the choice between a qualified and adverse opinion depends on whether the effects are pervasive. Because the misstatements are confined to inventory and warranty liabilities within one product line and the remaining statements are fairly stated, a qualified opinion is appropriate. Choice B is incorrect because exceeding materiality alone does not require an adverse opinion; pervasiveness is the determining factor.', 'hard', 4),

-- Q26: easy / L1 — Management's responsibility to correct misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, the responsibility for correcting misstatements identified during an audit rests with:', '["The external auditor, who must adjust the financial statements directly", "Those charged with governance, who must authorize every correction", "The engagement quality reviewer, who approves all audit adjustments", "Management, because they are responsible for the preparation and fair presentation of the financial statements"]'::jsonb, 3, 'Under AU-C 450.07, the auditor must communicate all misstatements accumulated during the audit to the appropriate level of management and request that management correct those misstatements. The responsibility for preparing and fairly presenting the financial statements rests with management under AU-C 200.A2. Choice A is incorrect because the auditor identifies and communicates misstatements but does not have authority to adjust the entity''s financial statements directly.', 'easy', 1),

-- Q27: easy / L2 — Applying clearly trivial threshold to a specific error
(1, 'Misstatements and Control Deficiencies', 'During the audit of Birchwood Catering Services, the auditor sets materiality at $75,000 and the clearly trivial threshold at $3,750. A $2,100 error in office supply expense is identified. Under AU-C 450, the auditor should:', '["Add the error to the summary of uncorrected misstatements and communicate it to management", "Disregard the error because it is below the clearly trivial threshold and need not be accumulated", "Communicate the error directly to those charged with governance as a control deficiency", "Reduce the clearly trivial threshold to capture the error in the summary"]'::jsonb, 1, 'Under AU-C 450.05, the auditor need not accumulate misstatements that are clearly trivial. Because the $2,100 error is below the $3,750 clearly trivial threshold, the auditor may disregard it without adding it to the summary of uncorrected misstatements. Choice A is incorrect because accumulation is required only for misstatements that exceed the clearly trivial threshold.', 'easy', 2),

-- Q28: medium / L2 — Omitted disclosure treated as a misstatement
(1, 'Misstatements and Control Deficiencies', 'While completing the audit of Evergreen Health Partners, the auditor discovers that management omitted the required related-party transaction disclosure for $425,000 in consulting fees paid to a board member''s firm. Overall materiality is $300,000. Under AU-C 450, the auditor should treat this omission as:', '["A control deficiency rather than a misstatement because the underlying transaction was properly recorded", "A scope limitation requiring a qualified or disclaimer of opinion", "A misstatement of the financial statements because omitted disclosures required by GAAP are included in the definition of misstatements", "An immaterial disclosure matter because the dollar amount of related-party transactions is typically excluded from materiality assessments"]'::jsonb, 2, 'Under AU-C 450.A1, misstatements include misstatements of disclosures, such as the omission of a disclosure required by the applicable financial reporting framework. The omitted related-party disclosure for $425,000, exceeding the $300,000 materiality, is both a misstatement and likely material. Choice A is incorrect because the correct recording of the underlying transaction does not excuse the omission of a required disclosure.', 'medium', 2),

-- Q29: easy / L1 — Definition of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Which of the following best describes uncorrected misstatements under AU-C 450?', '["Misstatements identified during the audit that management has not corrected", "Errors discovered after the audit report has been issued", "Differences between the auditor''s and management''s interpretation of GAAP that are resolved through negotiation", "Adjustments proposed by the auditor that exceed performance materiality"]'::jsonb, 0, 'Under AU-C 450.06, uncorrected misstatements are misstatements that the auditor has accumulated during the audit and that have not been corrected. The auditor requests management to correct all accumulated misstatements, and any that remain uncorrected are evaluated for their effect on the financial statements. Choice D is incorrect because uncorrected misstatements include all accumulated misstatements management declines to correct, not only those exceeding performance materiality.', 'easy', 1),

-- Q30: medium / L2 — Distinguishing significant deficiency from material weakness in scenario
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redwood Property Management, the auditor discovers that lease revenue reconciliations are performed only quarterly instead of monthly as required by company policy. During a three-month gap, a $45,000 billing error occurred but was detected and corrected at the next quarterly reconciliation. Overall materiality is $180,000. The auditor should most likely classify this control deficiency as:', '["Not reportable because the error was ultimately detected and corrected by the existing control", "A material weakness because any deviation from company policy over revenue represents a critical failure", "A control deficiency that does not merit reporting because the quarterly reconciliation functioned as designed", "A significant deficiency because the reduced frequency created a reasonable possibility that misstatements could fail to be detected on a timely basis, though the compensating quarterly review limited the magnitude"]'::jsonb, 3, 'Under AU-C 265.A8, a significant deficiency is a deficiency, or combination of deficiencies, in internal control that is less severe than a material weakness yet important enough to merit attention by those charged with governance. The reduced reconciliation frequency increased the risk window, but the quarterly review ultimately detected the error, limiting the magnitude below a material weakness. Choice B is incorrect because the quarterly compensating control reduced the reasonable possibility of a material misstatement.', 'medium', 2)
;

COMMIT;
